import { describe, it, expect } from 'vitest';
import git from 'isomorphic-git';
import {
  recordEvent, replayEvents,
  getDatabase, getAllNodes, insertNode, createTestContext,
  HiveContext, Node,
} from '@hive/core';

const branch = 'hive-test';

async function bootstrap(): Promise<{ ctx: HiveContext; dir: string }> {
  const dir = '/test-repo';
  const ctx = await createTestContext(dir);
  ctx.fs.mkdirSync(dir, { recursive: true });
  ctx.fs.mkdirSync(`${dir}/.hive`, { recursive: true });
  await git.init({ fs: ctx.fs as any, dir, defaultBranch: 'main' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.name', value: 'Test User' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.email', value: 'test@example.com' });
  ctx.fs.writeFileSync(`${dir}/README.md`, '# Test');
  await git.add({ fs: ctx.fs as any, dir, filepath: 'README.md' });
  await git.commit({ fs: ctx.fs as any, dir, message: 'Initial commit',
    author: { name: 'Test User', email: 'test@example.com' } });
  await git.branch({ fs: ctx.fs as any, dir, ref: branch });
  return { ctx, dir };
}

async function addNode(ctx: HiveContext, title: string): Promise<string> {
  const id = await recordEvent(ctx, { type: 'add', nodeType: 'decision', content: title, confidence: 90 }, branch);
  const db = getDatabase(ctx);
  const now = new Date().toISOString();
  const node: Node = { change_id: id, branch, node_type: 'decision', title, status: 'pending', created_at: now, updated_at: now };
  insertNode(db, node);
  return id;
}

describe('gap: the watermark must mean everything before it is in the view', () => {
  it('replays pre-existing event commits that predate the first local write on a cold db', async () => {
    const { ctx } = await bootstrap();

    // Pre-existing event commit, exactly as on a fresh clone: the git log carries
    // this decision, but recordEvent('add') never materialises it into the local
    // db (P6). It still advances the watermark to this commit (P5, line 163).
    const preId = await recordEvent(
      ctx,
      { type: 'add', nodeType: 'decision', content: 'pre-existing decision', confidence: 90 },
      branch,
    );

    // First local write on the cold db: adds ONE new node and pushes the
    // watermark to the new HEAD.
    await addNode(ctx, 'brand new decision');

    // Materialise the view, exactly as `hive nodes` does. lastSyncHash is set,
    // the db exists, force is false, and lastSyncHash === HEAD, so replayEvents
    // takes its early-return path (lines 289 false -> 315/316 return).
    await replayEvents(ctx, branch);

    // The pre-existing decision must appear in the materialised view.
    const found = getAllNodes(getDatabase(ctx)).find(n => n.change_id === preId);
    expect(found?.change_id).toBe(preId);
  });
});
